with flattened_attrs as (select id, plan, aggregate(tier_prices, 0.0D, (acc, p) -> acc + p, acc -> round(acc / size(tier_prices), 2)) as avg_tier_price, transform(tier_prices, (p, i) -> round(p * tier_limits[i], 2)) as tier_revenue_caps, zip_with(tier_prices, discounts, (p, d) -> round(p * (1 - d), 2)) as net_prices, element_at(tier_prices, 1) as entry_price, slice(tier_limits, 1, 2) as first_two_limits from price_tiers where plan = 'enterprise') select id, avg_tier_price, entry_price, ntile(10) over (partition by plan order by entry_price desc, id) as entry_price_bucket, row_number() over (partition by plan order by avg_tier_price desc, id) as seq_no from flattened_attrs where plan in ('starter', 'pro');
